struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { data: s.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.data.len() && matches!(self.data[self.pos], b' ' | b'\t' | b'\n' | b'\r') {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<u8> {
        self.data.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<u8> {
        let b = self.peek();
        if b.is_some() {
            self.pos += 1;
        }
        b
    }

    fn expect(&mut self, c: u8) -> Result<(), String> {
        self.skip_ws();
        match self.next() {
            Some(b) if b == c => Ok(()),
            _ => Err(format!("Expected '{}' at position {}", c as char, self.pos.saturating_sub(1))),
        }
    }

    fn parse_value(&mut self) -> Result<Json, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(Json::Str),
            Some(b't') => self.parse_literal("true").map(|_| Json::Bool(true)),
            Some(b'f') => self.parse_literal("false").map(|_| Json::Bool(false)),
            Some(b'n') => self.parse_literal("null").map(|_| Json::Null),
            Some(b'-') | Some(b'0'..=b'9') => self.parse_number(),
            _ => Err(format!("Unexpected character at position {}", self.pos)),
        }
    }

    fn parse_literal(&mut self, expected: &str) -> Result<(), String> {
        for c in expected.as_bytes() {
            if self.next() != Some(*c) {
                return Err(format!("Expected literal '{}' at position {}", expected, self.pos));
            }
        }

