    if (a is NSNull) != (b is NSNull) { return false }

    if let strA = a as? String {
        if let strB = b as? String { return strA == strB }
        return false
    }
    if b is String { return false }

    if let numA = a as? NSNumber {
        if let numB = b as? NSNumber {
            let aIsBool = CFGetTypeID(numA) == CFBooleanGetTypeID()
            let bIsBool = CFGetTypeID(numB) == CFBooleanGetTypeID()
            if aIsBool && bIsBool { return numA.boolValue == numB.boolValue }
            if aIsBool != bIsBool { return false }
            return numA.doubleValue == numB.doubleValue
        }
        return false
    }
    if b is NSNumber { return false }

    if let arrA = a as? [Any] {
        if let arrB = b as? [Any] {
            if arrA.count != arrB.count { return false }
            for i in 0..<arrA.count {
                if !jsonEqual(arrA[i], arrB[i]) { return false }
            }
            return true
        }
        return false
    }
    if b is [Any] { return false }

    if let dictA = a as? [String: Any] {
        if let dictB = b as? [String: Any] {
            if dictA.count != dictB.count { return false }
            for (key, valA) in dictA {
                guard let valB = dictB[key] else { return false }
                if !jsonEqual(valA, valB) { return false }
            }
            return true
        }
        return false
    }

