    if (len >= 2 && s[0] == '"' && s[len - 1] == '"') {
        memmove(s, s + 1, len - 2);
        s[len - 2] = '\0';
    }
    return s;
}

static void format_comma(double val, int decimals, char *buf, int bufsize) {
    char tmp[128];
    if (decimals == 0) {
        snprintf(tmp, sizeof(tmp), "%lld", (long long)llround(val));
    } else {
        snprintf(tmp, sizeof(tmp), "%.*f", decimals, val);
    }

    int len = (int)strlen(tmp);
    int dotpos = -1;
    for (int i = 0; i < len; i++) {
        if (tmp[i] == '.') { dotpos = i; break; }
    }
    int intlen = (dotpos == -1) ? len : dotpos;

    int pos = 0;
    for (int i = 0; i < intlen; i++) {
        if (i > 0 && (intlen - i) % 3 == 0) {
            if (pos + 1 < bufsize) buf[pos++] = ',';
        }
        if (pos + 1 < bufsize) buf[pos++] = tmp[i];
    }
    if (dotpos != -1) {
        for (int i = dotpos; i < len; i++) {
            if (pos + 1 < bufsize) buf[pos++] = tmp[i];
        }
    }
    buf[pos] = '\0';
}

