static void trim(char *s)
{
    size_t len = strlen(s);
    while (len > 0 &&
           (s[len - 1] == '\n' || s[len - 1] == '\r' ||
            s[len - 1] == ' '  || s[len - 1] == '\t')) {
        s[len - 1] = '\0';
        len--;
    }
}

static char *run_cmd(const char *cmd)
{
    FILE *f = popen(cmd, "r");
    if (!f)
        return NULL;

    size_t cap = 4096;
    char *buf = malloc(cap);
    if (!buf) {
        pclose(f);
        return NULL;
    }

    size_t total = 0;
    buf[0] = '\0';

    while (total + 1 < cap) {
        size_t n = fread(buf + total, 1, cap - total - 1, f);
        if (n == 0)
            break;
        total += n;
        buf[total] = '\0';
        if (n < cap - total - 1)
            break;
        cap *= 2;
        char *tmp = realloc(buf, cap);
        if (!tmp) {
            free(buf);
            pclose(f);
            return NULL;
        }
        buf = tmp;
    }

    pclose(f);
    trim(buf);
    return buf;
}

