def mat_mul(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def det_2x2(m):
    return m[0][0] * m[1][1] - m[0][1] * m[1][0]

def det_3x3(m):
    return (m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
            - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
            + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]))

def det(m):
    n = len(m)
    if n == 1:
        return m[0][0]
    if n == 2:
        return det_2x2(m)
    if n == 3:
        return det_3x3(m)
    result = 0
    for j in range(n):
        minor = [row[:j] + row[j+1:] for row in m[1:]]
        sign = 1 if j % 2 == 0 else -1
        result += sign * m[0][j] * det(minor)
    return result

